{{
Abbildung/display
|name=
| {{op:Affine Ebene| K |}} | {{op:KSpek|K[M]}} \hookrightarrow {{op:Affiner Raum| 3 |K}}
| (s,t) | {{makl| s ,st ,t^2 |}}
|SZ=.
}}
